"use client";

import { AnimatePresence, animate, motion, useReducedMotion, type AnimationPlaybackControls, type Transition } from "motion/react";
import { type KeyboardEvent, useCallback, useEffect, useRef, useState } from "react";

import { cn } from "@/lib/utils";

/** Props for a voice note. */
export interface VoiceNoteProps {
  /** The recording. Any format the browser plays. */
  src: string;
  /** Names the voice note for screen readers, such as "Voice message from Sam". */
  label: string;
  /**
   * Loudness of the recording in even slices, each from 0 to 1, drawn as the
   * bars of the waveform. Measure it once, when the note is recorded. Without
   * it, every bar sits at one height and the waveform still scrubs.
   */
  peaks?: readonly number[];
  /** Length in seconds, shown until the browser reads the length from the file. */
  duration?: number;
  className?: string;
}

const SPEEDS = [1, 1.5, 2] as const;
const FLAT_PEAKS: readonly number[] = Array.from({ length: 32 }, () => 0.4);
// Arrow keys move one second and Page keys five, as a media player's seek bar does.
const KEY_STEPS = new Map([
  ["ArrowLeft", -1],
  ["ArrowDown", -1],
  ["ArrowRight", 1],
  ["ArrowUp", 1],
  ["PageDown", -5],
  ["PageUp", 5],
]);
// Static classes, so Tailwind generates every height a bar can take.
const BAR_HEIGHTS = ["h-1", "h-2", "h-3", "h-4", "h-5", "h-6", "h-7", "h-8"] as const;

const SWAP: Transition = { type: "spring", duration: 0.3, bounce: 0 };
// A fade is not motion, so reduced motion keeps it and drops the scale and blur.
const FADE: Transition = { duration: 0.15 };

// Only one note plays at a time: starting one pauses whichever was playing.
let playingNow: HTMLAudioElement | null = null;

function formatTime(seconds: number): string {
  const whole = Math.max(0, Math.floor(seconds));
  return `${Math.floor(whole / 60)}:${String(whole % 60).padStart(2, "0")}`;
}

function barHeight(peak: number): (typeof BAR_HEIGHTS)[number] {
  const level = Math.round(Math.min(1, Math.max(0, peak)) * (BAR_HEIGHTS.length - 1));
  return BAR_HEIGHTS[level];
}

function Bars({ peaks }: { peaks: readonly number[] }) {
  return (
    // Bars shrink to a hairline on a narrow screen, so every slice fits and the
    // position under the finger still matches the sound.
    <span className="flex h-full w-full items-center justify-between gap-px">
      {peaks.map((peak, index) => (
        // The bars never reorder, so a slice's position is its identity.
        <span key={index} className={cn("min-w-px max-w-1 flex-1 rounded-full bg-current", barHeight(peak))} />
      ))}
    </span>
  );
}

function PlayGlyph() {
  return (
    <svg viewBox="0 0 16 16" aria-hidden="true" className="size-4">
      <path d="M5 3.4v9.2a.6.6 0 0 0 .9.5l7.4-4.6a.6.6 0 0 0 0-1L5.9 2.9a.6.6 0 0 0-.9.5Z" fill="currentColor" />
    </svg>
  );
}

function PauseGlyph() {
  return (
    <svg viewBox="0 0 16 16" aria-hidden="true" className="size-4">
      <rect x="3.5" y="3" width="3" height="10" rx="1" fill="currentColor" />
      <rect x="9.5" y="3" width="3" height="10" rx="1" fill="currentColor" />
    </svg>
  );
}

function RetryGlyph() {
  return (
    <svg viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth="1.75" aria-hidden="true" className="size-4">
      <path d="M13 8a5 5 0 1 1-1.6-3.7" strokeLinecap="round" />
      <path d="M13 2.5v3h-3" strokeLinecap="round" strokeLinejoin="round" />
    </svg>
  );
}

/**
 * Plays a recorded voice message. The waveform fills as the note plays, and a
 * drag or the arrow keys move the playhead. A native range input does the
 * seeking underneath, so it keeps the slider role and its screen reader support.
 */
export function VoiceNote(props: VoiceNoteProps) {
  // A new recording starts from a clean player: no old position, speed or failure.
  return <VoiceNotePlayer key={props.src} {...props} />;
}

function VoiceNotePlayer({ src, label, peaks = FLAT_PEAKS, duration: givenDuration = 0, className }: VoiceNoteProps) {
  const audio = useRef<HTMLAudioElement>(null);
  const playedWindow = useRef<HTMLSpanElement>(null);
  const playedBars = useRef<HTMLSpanElement>(null);
  const rewind = useRef<AnimationPlaybackControls | null>(null);
  const [playing, setPlaying] = useState(false);
  const [failed, setFailed] = useState(false);
  const [duration, setDuration] = useState(givenDuration);
  const [position, setPosition] = useState(0);
  const [speed, setSpeed] = useState<(typeof SPEEDS)[number]>(1);
  const reduceMotion = useReducedMotion();

  // The played bars sit in a window that slides in from the left while the bars
  // inside slide the other way, so they hold still and only the edge moves. It
  // follows the audio clock once a frame, with transforms and no React render.
  const paint = useCallback((fraction: number) => {
    const hiddenShare = (1 - fraction) * 100;
    if (playedWindow.current) playedWindow.current.style.translate = `${-hiddenShare}% 0`;
    if (playedBars.current) playedBars.current.style.translate = `${hiddenShare}% 0`;
  }, []);

  useEffect(() => {
    if (!playing) return;
    let frame = 0;
    const tick = () => {
      const element = audio.current;
      if (element && duration > 0) paint(Math.min(1, element.currentTime / duration));
      frame = requestAnimationFrame(tick);
    };
    frame = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(frame);
  }, [playing, duration, paint]);

  useEffect(() => {
    if (audio.current) audio.current.playbackRate = speed;
  }, [speed]);

  // A cached file can report its length, or fail, before React attaches the
  // handlers below, so read both once the element is in the page.
  useEffect(() => {
    const element = audio.current;
    if (!element) return;
    if (Number.isFinite(element.duration) && element.duration > 0) setDuration(element.duration);
    if (element.error) setFailed(true);
    return () => {
      if (playingNow === element) playingNow = null;
    };
  }, []);

  const seek = (seconds: number) => {
    const element = audio.current;
    if (!element || duration <= 0) return;
    const next = Math.min(duration, Math.max(0, seconds));
    rewind.current?.stop();
    element.currentTime = next;
    setPosition(next);
    paint(next / duration);
  };

  const toggle = () => {
    const element = audio.current;
    if (!element) return;
    if (failed) {
      // Try the file again: a dropped connection is often the only fault.
      setFailed(false);
      element.load();
    } else if (!element.paused) {
      element.pause();
      return;
    }
    element.play().catch(() => {
      // A pause before playback starts also rejects, and that is not a fault.
      // Only a media error on the element means the file cannot play.
      if (element.error) setFailed(true);
    });
  };

  const onKeyDown = (event: KeyboardEvent<HTMLInputElement>) => {
    const step = KEY_STEPS.get(event.key);
    if (step !== undefined) {
      event.preventDefault();
      seek(position + step);
    } else if (event.key === "Home" || event.key === "End") {
      event.preventDefault();
      seek(event.key === "Home" ? 0 : duration);
    } else if (event.key === " ") {
      // Space plays and pauses from the waveform, as it does in a media player.
      event.preventDefault();
      toggle();
    }
  };

  const glyph = failed ? "retry" : playing ? "pause" : "play";
  const showElapsed = playing || position > 0;
  const timeText = failed ? "Unavailable" : formatTime(showElapsed ? position : duration);
  const swap = reduceMotion ? FADE : SWAP;
  const hidden = reduceMotion ? { opacity: 0 } : { opacity: 0, scale: 0.6, filter: "blur(0.125rem)" };

  return (
    <div
      role="group"
      aria-label={label}
      data-state={failed ? "failed" : playing ? "playing" : "paused"}
      className={cn("flex w-full max-w-sm items-center gap-3 rounded-2xl border border-border bg-card py-2 pl-2 pr-3 text-card-foreground", className)}
    >
      <audio
        ref={audio}
        src={src}
        preload="metadata"
        onPlay={(event) => {
          rewind.current?.stop();
          if (playingNow && playingNow !== event.currentTarget) playingNow.pause();
          playingNow = event.currentTarget;
          setPlaying(true);
        }}
        onPause={() => setPlaying(false)}
        onTimeUpdate={(event) => setPosition(event.currentTarget.currentTime)}
        // A recorded WebM file can report an infinite length until it is read through.
        onDurationChange={(event) => {
          const length = event.currentTarget.duration;
          if (Number.isFinite(length) && length > 0) setDuration(length);
        }}
        // Loading a file resets the speed, so a retry keeps the one the person chose.
        onLoadedMetadata={(event) => {
          event.currentTarget.playbackRate = speed;
        }}
        onEnded={(event) => {
          setPlaying(false);
          event.currentTarget.currentTime = 0;
          setPosition(0);
          // The fill rewinds to the start, so the note reads as ready to play again.
          // The last frame can land just short of the end, so finish the fill first.
          paint(1);
          if (reduceMotion) paint(0);
          else rewind.current = animate(1, 0, { ...SWAP, onUpdate: paint });
        }}
        onError={() => {
          setFailed(true);
          setPlaying(false);
        }}
      />
      <button
        type="button"
        onClick={toggle}
        aria-label={glyph === "retry" ? "Try again" : glyph === "pause" ? "Pause" : "Play"}
        className="relative grid size-11 shrink-0 cursor-pointer touch-manipulation place-items-center rounded-full bg-primary text-primary-foreground outline-none active:scale-95 focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-card motion-safe:transition motion-safe:duration-150 sm:size-10"
      >
        <AnimatePresence mode="popLayout" initial={false}>
          <motion.span
            key={glyph}
            initial={hidden}
            animate={{ opacity: 1, scale: 1, filter: "blur(0rem)" }}
            exit={hidden}
            transition={swap}
            className="grid place-items-center"
          >
            {glyph === "retry" ? <RetryGlyph /> : glyph === "pause" ? <PauseGlyph /> : <PlayGlyph />}
          </motion.span>
        </AnimatePresence>
      </button>
      <span className="relative flex h-11 min-w-0 flex-1 items-center sm:h-8">
        <span aria-hidden="true" className="absolute inset-0 overflow-hidden">
          <span className="absolute inset-0 flex items-center text-muted-foreground/40">
            <Bars peaks={peaks} />
          </span>
          <span ref={playedWindow} className="absolute inset-0 -translate-x-full overflow-hidden">
            <span ref={playedBars} className="absolute inset-0 flex translate-x-full items-center text-primary">
              <Bars peaks={peaks} />
            </span>
          </span>
        </span>
        <input
          type="range"
          min={0}
          max={duration || 1}
          step="any"
          value={position}
          disabled={failed || duration <= 0}
          aria-label="Playback position"
          aria-valuetext={`${formatTime(position)} of ${formatTime(duration)}`}
          onChange={(event) => seek(Number(event.target.value))}
          onKeyDown={onKeyDown}
          className="peer absolute inset-0 h-full w-full cursor-pointer touch-pan-y appearance-none opacity-0 disabled:cursor-not-allowed [&::-moz-range-thumb]:size-0 [&::-webkit-slider-thumb]:size-0 [&::-webkit-slider-thumb]:appearance-none"
        />
        <span
          aria-hidden="true"
          className="pointer-events-none absolute -inset-x-1 inset-y-1 rounded-md peer-focus-visible:ring-2 peer-focus-visible:ring-ring"
        />
      </span>
      <span aria-hidden="true" className="min-w-9 shrink-0 text-right text-xs tabular-nums text-muted-foreground">
        {timeText}
      </span>
      <span role="status" className="sr-only">
        {failed ? "This voice message could not load." : ""}
      </span>
      <button
        type="button"
        onClick={() => setSpeed(SPEEDS[(SPEEDS.indexOf(speed) + 1) % SPEEDS.length])}
        aria-label={`Playback speed, ${speed} times`}
        className="relative grid h-11 min-w-11 shrink-0 cursor-pointer touch-manipulation place-items-center rounded-full bg-muted px-2 text-xs font-medium tabular-nums text-foreground outline-none hover:bg-muted/70 active:scale-95 focus-visible:ring-2 focus-visible:ring-ring motion-safe:transition motion-safe:duration-150 sm:h-7 sm:before:absolute sm:before:inset-x-0 sm:before:-inset-y-1 sm:min-w-10"
      >
        {speed}×
      </button>
    </div>
  );
}
